using System.Text.Json.Serialization;
namespace HakutaiKagami.Core.Contracts;
public enum BrokerKind { Letter,Purchase }
public enum BrokerAction { Accept,Buy,Deliver,Settle,Return }
public sealed record BrokerInput(EntityId Id,BrokerAction Action,EntityId? Job=null,EntityId? Issuer=null,BrokerKind Kind=BrokerKind.Letter,bool Personal=false);
public sealed record BrokerTerms(EntityId Id,EntityId Issuer,EntityId Worker,EntityId Recipient,EntityId Home,EntityId Destination,BrokerKind Kind,long Quantity,long Advance,long Fee,long Until,bool Personal){[JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingNull)]public WorkAbilitySnapshot? Abilities{get;init;}}
public sealed record BrokerEntry(BrokerInput Input,EntityId Actor,EntityId Site,long At,long Revision,BrokerTerms? Terms,long Cost);
public sealed record BrokerState(int Schema,string Policy,BrokerEntry[] Entries);
public sealed record BrokerJob(BrokerTerms Terms,string Phase,long Cash,long Cargo,long? DeliveredAt,bool Success);
public static class BrokerWork
{
 public const string Policy="known-local-broker-sealed-letter-escrow-purchase-v1";
 internal static BrokerEntry[] Entries(ContractWorld w)=>w.BrokerWork?.Entries??[];
 static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool ok,string why){if(!ok)throw new InvalidDataException(why);}
 static bool Before(BrokerEntry e,long at,long rev)=>e.At<at||e.At==at&&e.Revision<rev;
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Entries(w).Any(e=>e.Input.Id==id);
 public static BrokerJob[] Jobs(ContractWorld w,long at=long.MaxValue,long rev=long.MaxValue){var jobs=new Dictionary<EntityId,BrokerJob>();foreach(var e in Entries(w).Where(e=>Before(e,at,rev))){if(e.Terms is {} t){jobs.Add(t.Id,new(t,"引受中",t.Advance,0,null,false));continue;}var j=jobs[e.Input.Job!.Value];j=e.Input.Action switch{BrokerAction.Buy=>j with{Phase="買付済み",Cash=j.Cash-e.Cost,Cargo=j.Terms.Quantity},BrokerAction.Deliver=>j with{Phase="受領証を持帰り",Cargo=0,DeliveredAt=e.At,Success=e.At<=j.Terms.Until},BrokerAction.Settle=>j with{Phase="精算済み",Cash=0},BrokerAction.Return=>j with{Phase="返納済み",Cash=0,Cargo=0},_=>throw new InvalidDataException("仕事の操作が不正です")};jobs[j.Terms.Id]=j;}return jobs.Values.ToArray();}
 public static bool Closed(BrokerJob j)=>j.Phase is "精算済み" or "返納済み";
 public static long CarryingMass(ContractWorld w,EntityId actor,long at,long rev)=>Jobs(w,at,rev).Where(j=>j.Terms.Worker==actor&&!Closed(j)).Sum(j=>j.Cargo);
 public static BrokerTerms[] Offers(ContractWorld w,EntityId worker,EntityId id,BrokerKind kind,bool personal=false){if(!NewGameWork.Enabled(w)||!MaterialMarkets.Enabled(w)||SocialWorld.Site(w,worker) is not {} site||Jobs(w).Any(j=>j.Terms.Worker==worker&&!Closed(j)))return [];return w.NewGame!.Start.People.Where(p=>p.Id!=worker.Value&&SocialWorld.Site(w,new(p.Id))==site&&w.Characters.Any(c=>c.Id.Value==p.Id&&c.Life==LifeState.Adult)).Where(p=>!personal||WorkRelations.Facts(w,new(p.Id),worker).Length>0).Select(p=>{var recipient=w.NewGame.Start.People.Where(d=>d.Id!=p.Id&&d.Id!=worker.Value&&d.Site!=site.Value&&d.Faction!=null&&d.Faction==p.Faction).OrderBy(d=>d.Id,StringComparer.Ordinal).FirstOrDefault();return new BrokerTerms(id,new(p.Id),worker,kind==BrokerKind.Purchase?new(p.Id):new(recipient?.Id??p.Id),site,kind==BrokerKind.Purchase?site:new(recipient?.Site??site.Value),kind,personal?20:5,kind==BrokerKind.Purchase?(personal?300:100):0,AbilityEffects.Fee(kind,personal,AbilityEffects.Terms(w,worker,w.ElapsedSeconds)),w.ElapsedSeconds+30*86400,personal){Abilities=AbilityEffects.Terms(w,worker,w.ElapsedSeconds)};}).Where(t=>t.Kind==BrokerKind.Purchase||t.Destination!=site).ToArray();}
 public static long Net(ContractWorld w,EntityId wallet,long at,long rev){long n=0;foreach(var e in Entries(w).Where(e=>Before(e,at,rev))){if(e.Terms is {} t){if(NewGameWork.Wallet(t.Issuer)==wallet)n=checked(n-t.Advance-t.Fee);continue;}var j=Jobs(w,e.At,e.Revision).Single(j=>j.Terms.Id==e.Input.Job);if(e.Input.Action is BrokerAction.Settle or BrokerAction.Return){long fee=e.Input.Action==BrokerAction.Settle&&j.Success?j.Terms.Fee:0;if(NewGameWork.Wallet(j.Terms.Issuer)==wallet)n=checked(n+j.Cash+j.Terms.Fee-fee);if(NewGameWork.Wallet(j.Terms.Worker)==wallet)n=checked(n+fee);}}return n;}
 internal static TreasuryEntry[] Purchases(ContractWorld w,long at,long rev)=>Entries(w).Where(e=>e.Input.Action==BrokerAction.Buy&&Before(e,at,rev)).Select(e=>new TreasuryEntry(new(e.Input.Id,TreasuryAction.Buy,e.Site,"wood",Jobs(w,e.At,e.Revision).Single(j=>j.Terms.Id==e.Input.Job).Terms.Quantity),e.Actor,e.At,e.Revision,null,null,new(new("payment:broker/"+e.Input.Id.Value.Replace(':','/')),e.Input.Id,e.Actor,new("org:market/"+e.Site.Value.Replace(':','/')),e.Cost,e.At,e.Revision))).ToArray();
 internal static long Spent(ContractWorld w,long at,long rev)=>Purchases(w,at,rev).Sum(e=>e.Payment!.Amount);
 internal static void Rewind(ContractWorld w,long at,long rev){if(w.BrokerWork!=null){var es=Entries(w).Where(e=>e.At<at||e.At==at&&e.Revision<=rev).ToArray();w.BrokerWork=es.Length==0?null:w.BrokerWork with{Entries=es};}}
 public static long Deposited(ContractWorld w,EntityId owner)=>Jobs(w).Where(j=>j.Terms.Kind==BrokerKind.Purchase&&j.Terms.Issuer==owner&&j.DeliveredAt!=null).Sum(j=>j.Terms.Quantity);
 public static void Execute(ContractWorld w,BrokerInput i,EntityId actor){Need(NewGameWork.Enabled(w)&&Enum.IsDefined(i.Action)&&Enum.IsDefined(i.Kind)&&EntityId.IsValid(i.Id.Value),"仕事の入力を確認してください");var site=SocialWorld.Site(w,actor)??throw new InvalidDataException("移動中は受渡しできません");BrokerTerms? terms=null;long cost=0;if(i.Action==BrokerAction.Accept){Need(i.Job==null&&i.Issuer!=null,"依頼主を選んでください");terms=Offers(w,actor,i.Id,i.Kind,i.Personal).Single(t=>t.Issuer==i.Issuer);Need(TransportWork.WalletBefore(w,terms.Issuer,w.ElapsedSeconds,w.CommitSequence)>=terms.Advance+terms.Fee,"依頼主が預り金と報酬を用意できません");}
 else {Need(i.Job!=null&&i.Issuer==null&&!i.Personal&&i.Kind==BrokerKind.Letter,"引受原本を指定してください");var j=Jobs(w).Single(j=>j.Terms.Id==i.Job);Need(j.Terms.Worker==actor&&!Closed(j),"本人の未精算の仕事ではありません");var t=j.Terms;switch(i.Action){case BrokerAction.Buy:Need(t.Abilities==null||w.ElapsedSeconds>=t.Abilities.ReadyAt,"買付の段取りが整うまでお待ちください");Need(t.Kind==BrokerKind.Purchase&&j.Phase=="引受中"&&w.ElapsedSeconds<=t.Until,"買付できない状態・期限です");var m=RegionalTrade.SnapshotAt(w,w.ElapsedSeconds,w.CommitSequence).Markets.Single(m=>m.Site==site);cost=checked(RegionalTrade.QuotePrice(m,true,"wood")*t.Quantity);Need(RegionalTrade.StockFree(RegionalTrade.SnapshotAt(w,w.ElapsedSeconds,w.CommitSequence),site,"wood")>=t.Quantity&&cost<=j.Cash&&SocialAssets.CarryingMass(w,actor)+(w.Trade?.Deals.Where(d=>d.Phase is TradePhase.Carrying or TradePhase.SaleQuoted or TradePhase.ReturnRequired).Sum(d=>d.Amount*MaterialMarkets.MassKg(d.Commodity))??0)+t.Quantity<=100,"市場在庫・預り金・携行100kgを確認してください");break;
 case BrokerAction.Deliver:Need(j.DeliveredAt==null&&(t.Kind==BrokerKind.Letter||j.Phase=="買付済み")&&site==t.Destination&&SocialWorld.Site(w,t.Recipient)==site,"指定された現地の相手へ実物を渡してください");break;
 case BrokerAction.Settle:Need(j.DeliveredAt!=null&&site==t.Home&&SocialWorld.Site(w,t.Issuer)==site,"受領証を依頼主へ持ち帰ってください");break;
 case BrokerAction.Return:Need(j.DeliveredAt==null&&j.Cargo==0&&site==t.Home&&SocialWorld.Site(w,t.Issuer)==site,"未納品の荷物は先に納めてください。預り金は現地で返します");break;
 default:throw new InvalidDataException("未対応の仕事です");}}
 w.BrokerWork??=new(1,Policy,[]);w.BrokerWork=w.BrokerWork with{Entries=[..Entries(w),new(i,actor,site,w.ElapsedSeconds,w.CommitSequence,terms,cost)]};}
 internal static void Tick(ContractWorld w,bool autonomous=false){if(w.BrokerWork==null)return;foreach(var job in Jobs(w).Where(j=>!Closed(j)&&j.Terms.Worker!=w.PlayerControl).ToArray()){var a=job.Terms.Worker;var site=SocialWorld.Site(w,a);BrokerAction? action=job.DeliveredAt!=null&&site==job.Terms.Home?BrokerAction.Settle:job.Terms.Kind==BrokerKind.Purchase&&job.Phase=="引受中"?BrokerAction.Buy:site==job.Terms.Destination?BrokerAction.Deliver:null;if(action!=null)TransactionalWorld.TryApply(w,c=>Execute(c,new(new("request:broker-npc/"+w.CommitSequence+"/"+a.Value.Replace(':','/')),action.Value,job.Terms.Id),a));}
 if(!autonomous||w.ElapsedSeconds<86400||Entries(w).Any(e=>e.Input.Action==BrokerAction.Accept&&e.Actor!=w.PlayerControl&&e.At/86400==w.ElapsedSeconds/86400))return;
 var playerSite=SocialWorld.Site(w,w.PlayerControl);foreach(var person in w.NewGame!.Start.People.Where(p=>p.Id!=w.PlayerControl.Value&&SocialWorld.Site(w,new(p.Id))==playerSite).OrderBy(p=>p.Id,StringComparer.Ordinal)){var actor=new EntityId(person.Id);if(Jobs(w).Any(j=>j.Terms.Worker==actor&&!Closed(j)))continue;var id=new EntityId("request:broker-day/"+w.ElapsedSeconds/86400+"/"+actor.Value.Replace(':','/'));var offer=Offers(w,actor,id,BrokerKind.Purchase).FirstOrDefault(t=>t.Issuer!=w.PlayerControl&&w.NewGame.Start.People.Single(p=>p.Id==t.Issuer.Value).Faction==person.Faction);if(offer!=null&&TransactionalWorld.TryApply(w,c=>Execute(c,new(id,BrokerAction.Accept,Issuer:offer.Issuer,Kind:BrokerKind.Purchase),actor)))break;}}

 public static void Validate(ContractWorld w,ContractWorld? prior){if(w.BrokerWork==null){Need(prior?.BrokerWork==null,"仕事の原本が消えています");return;}var es=Entries(w);Need(NewGameWork.Enabled(w)&&w.BrokerWork.Schema==1&&w.BrokerWork.Policy==Policy&&es.Length>0,"仕事の保存形式が不正です");if(prior?.BrokerWork!=null)Need(ContractJson.CanonicalHash(es.Take(prior.BrokerWork.Entries.Length).ToArray())==ContractJson.CanonicalHash(prior.BrokerWork.Entries),"過去の仕事原本が変更されています");long rev=0,at=0;var jobs=new Dictionary<EntityId,BrokerJob>();var ids=new HashSet<EntityId>();foreach(var e in es){Need(ids.Add(e.Input.Id)&&e.Revision>rev&&e.Revision<=w.CommitSequence&&e.At>=at&&e.At<=w.ElapsedSeconds&&e.Cost>=0&&(e.Input.Action==BrokerAction.Buy||e.Cost==0),"仕事の順序・重複が不正です");Need(TransportWork.At(w,e.Actor,e.Site,e.At,e.Revision,true),"当時の実際の所在が違います");if(e.Terms is {} t){Need(e.Input.Action==BrokerAction.Accept&&t.Id==e.Input.Id&&t.Worker==e.Actor&&t.Issuer==e.Input.Issuer&&t.Kind==e.Input.Kind&&t.Personal==e.Input.Personal&&(!t.Personal||WorkRelations.Facts(w,t.Issuer,t.Worker).Any(f=>f.At<e.At||f.At==e.At&&Entries(w).Any(b=>b.Input.Id.Value==f.Basis&&b.Revision<e.Revision)))&&t.Home==e.Site&&t.Advance==(t.Kind==BrokerKind.Purchase?(t.Personal?300:100):0)&&t.Quantity==(t.Personal?20:5)&&t.Abilities==AbilityEffects.Terms(w,t.Worker,e.At)&&t.Fee==AbilityEffects.Fee(t.Kind,t.Personal,t.Abilities)&&t.Until==e.At+30*86400&&e.Cost==0&&!jobs.Values.Any(j=>j.Terms.Worker==e.Actor&&!Closed(j))&&TransportWork.At(w,t.Issuer,t.Home,e.At,e.Revision,true),"引受条件・預り金・面前の依頼主が不正です");Need(TransportWork.WalletBefore(w,t.Issuer,e.At,e.Revision)>=t.Advance+t.Fee,"依頼主の銭が不足しています");var sourcePerson=w.NewGame!.Start.People.Single(p=>p.Id==t.Issuer.Value);var recipient=w.NewGame.Start.People.Where(p=>p.Id!=t.Issuer.Value&&p.Id!=t.Worker.Value&&p.Site!=t.Home.Value&&p.Faction!=null&&p.Faction==sourcePerson.Faction).OrderBy(p=>p.Id,StringComparer.Ordinal).FirstOrDefault();Need(t.Kind==BrokerKind.Purchase?t.Recipient==t.Issuer&&t.Destination==t.Home:recipient!=null&&recipient.Id==t.Recipient.Value&&recipient.Site==t.Destination.Value,"宛先は依頼主が知る同家の開始時住所に限ります");}else{Need(e.Input.Job!=null&&jobs.TryGetValue(e.Input.Job.Value,out var old)&&old.Terms.Worker==e.Actor&&!Closed(old),"原本・未精算の本人が違います");var j=jobs[e.Input.Job!.Value];var t0=j.Terms;switch(e.Input.Action){case BrokerAction.Buy:Need(t0.Abilities==null||e.At>=t0.Abilities.ReadyAt,"買付の準備時間が不足しています");Need(j.Phase=="引受中"&&t0.Kind==BrokerKind.Purchase&&e.At<=t0.Until&&e.Cost<=j.Cash&&Purchases(w,e.At,e.Revision+1).Any(p=>p.Input.Id==e.Input.Id)&&e.Cost==checked(RegionalTrade.QuotePrice(RegionalTrade.SnapshotAt(w,e.At,e.Revision).Markets.Single(m=>m.Site==e.Site),true,"wood")*t0.Quantity),"買付の原本・価格が違います");break;case BrokerAction.Deliver:Need(j.DeliveredAt==null&&(t0.Kind==BrokerKind.Letter||j.Cargo==t0.Quantity)&&e.Site==t0.Destination&&TransportWork.At(w,t0.Recipient,e.Site,e.At,e.Revision,true),"現物の納品先が違います");break;case BrokerAction.Settle:Need(j.DeliveredAt!=null&&e.Site==t0.Home&&TransportWork.At(w,t0.Issuer,e.Site,e.At,e.Revision,true),"受領証の帰還がありません");break;case BrokerAction.Return:Need(j.DeliveredAt==null&&j.Cargo==0&&e.Site==t0.Home&&TransportWork.At(w,t0.Issuer,e.Site,e.At,e.Revision,true),"返納の実物がありません");break;default:throw new InvalidDataException("仕事の操作が不正です");}}jobs=Jobs(w,e.At,e.Revision+1).ToDictionary(j=>j.Terms.Id);rev=e.Revision;at=e.At;}}
}
public sealed partial class WorldSession
{
 public CommandResult ManageBroker(BrokerInput i,long revision){lock(gate){var old=BrokerWork.Entries(state).SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(r=>r.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みの原本です");try{Change(w=>BrokerWork.Execute(w,i,w.PlayerControl));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"預り物・受領証・精算を記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
